function initHardwareCalculator() {
  const cpuSelect = document.getElementById('hw-cpu-select');
  const gpuSelect = document.getElementById('hw-gpu-select');
  const ramSelect = document.getElementById('hw-ram-select');
  if (!cpuSelect || !gpuSelect || !ramSelect) return;

  function recalculate() {
    const cpuKey = cpuSelect.value;
    const gpuKey = gpuSelect.value;
    const ramKey = ramSelect.value;

    const cpu = HW_DATABASE.cpus[cpuKey] || HW_DATABASE.cpus['amd-zen5-ai'];
    const gpu = HW_DATABASE.gpus[gpuKey] || HW_DATABASE.gpus['nv-rtx4070'];
    const ram = HW_DATABASE.rams[ramKey] || HW_DATABASE.rams['ram-32'];

    const tierBadge = document.getElementById('hw-tier-badge');
    const tokGenVal = document.getElementById('hw-tok-gen');
    const tokPromptVal = document.getElementById('hw-tok-prompt');
    const powerVal = document.getElementById('hw-power-env');
    const primaryModelVal = document.getElementById('hw-primary-model');
    const bgModelVal = document.getElementById('hw-bg-model');
    const bestQuantVal = document.getElementById('hw-best-quant');
    const driverStackVal = document.getElementById('hw-driver-stack');
    const verifyCmdVal = document.getElementById('hw-verify-cmd');
    const vramStatVal = document.getElementById('hw-vram-stat');
    const vramBarFill = document.getElementById('hw-vram-bar-fill');
    const ramStatVal = document.getElementById('hw-ram-stat');
    const ramBarFill = document.getElementById('hw-ram-bar-fill');
    const vectorIsaVal = document.getElementById('hw-vector-isa');
    const npuStatusVal = document.getElementById('hw-npu-status');
    const bandwidthVal = document.getElementById('hw-bandwidth-stat');

    let promptSpeed, genSpeed, vramUsedGB, vramTotalGB, vramPercent, ramUsedGB, ramPercent;
    let effectiveTier = gpu.tier;
    let effectiveTierLabel = gpu.tierLabel;

    const ramMultiplier = ram.capacity >= 64 ? 1.15 : (ram.capacity <= 8 ? 0.78 : 1.0);

    if (gpu.isUnified) {
      vramTotalGB = ram.capacity;
      const modelFootprint = Math.min(ram.usableAI * 0.65, 14.5);
      vramUsedGB = parseFloat(modelFootprint.toFixed(1));
      vramPercent = Math.min(95, Math.round((vramUsedGB / vramTotalGB) * 100));

      ramUsedGB = parseFloat((vramUsedGB + 2.2).toFixed(1));
      ramPercent = Math.min(98, Math.round((ramUsedGB / ram.capacity) * 100));

      promptSpeed = Math.round(gpu.tokPrompt * cpu.factor * ramMultiplier);
      genSpeed = Math.round(gpu.tokGen * cpu.factor * ramMultiplier);
    } else if (gpu.isCpuOnly) {
      vramTotalGB = 0;
      vramUsedGB = 0;
      vramPercent = 0;

      ramUsedGB = parseFloat(Math.min(ram.capacity * 0.75, 6.2).toFixed(1));
      ramPercent = Math.min(95, Math.round((ramUsedGB / ram.capacity) * 100));

      promptSpeed = Math.round(gpu.tokPrompt * cpu.factor * ramMultiplier);
      genSpeed = Math.round(gpu.tokGen * cpu.factor * ramMultiplier);
    } else {
      vramTotalGB = gpu.vram;
      vramUsedGB = Math.min(gpu.vram, gpu.vramFootprint);
      vramPercent = Math.min(100, Math.round((vramUsedGB / gpu.vram) * 100));

      ramUsedGB = parseFloat((2.4 + (ram.capacity * 0.06)).toFixed(1));
      ramPercent = Math.min(95, Math.round((ramUsedGB / ram.capacity) * 100));

      promptSpeed = Math.round(gpu.tokPrompt * cpu.factor);
      genSpeed = Math.round(gpu.tokGen * cpu.factor);

      if (ram.capacity <= 8 && gpu.vram >= 16) {
        effectiveTier = 'tier-2';
        effectiveTierLabel = 'Tier 2: System RAM Bottleneck (VRAM > RAM)';
      }
    }

    if (tierBadge) {
      tierBadge.className = 'hw-tier-badge ' + effectiveTier;
      tierBadge.textContent = effectiveTierLabel;
    }
    if (tokGenVal) tokGenVal.textContent = genSpeed;
    if (tokPromptVal) tokPromptVal.textContent = promptSpeed.toLocaleString();
    if (powerVal) powerVal.textContent = gpu.power;
    if (primaryModelVal) primaryModelVal.textContent = gpu.primaryModel;
    if (bgModelVal) bgModelVal.textContent = gpu.bgModel;
    if (bestQuantVal) bestQuantVal.textContent = ram.bestQuant;
    if (driverStackVal) driverStackVal.textContent = gpu.driver;
    if (verifyCmdVal) verifyCmdVal.textContent = gpu.verifyCmd;
    if (vectorIsaVal) vectorIsaVal.textContent = cpu.vector;
    if (npuStatusVal) npuStatusVal.textContent = cpu.npu;
    if (bandwidthVal) bandwidthVal.textContent = (gpu.bandwidth || 64) + ' GB/s';

    
    // Official Silicon Specifications HUD
    const specCores = document.getElementById('hw-spec-cores');
    const specFreq = document.getElementById('hw-spec-freq');
    const specTdp = document.getElementById('hw-spec-tdp');
    const specMem = document.getElementById('hw-spec-mem');
    const specSocket = document.getElementById('hw-spec-socket');
    const specStatus = document.getElementById('hw-spec-status');

    if (specCores) specCores.textContent = (cpu.cores && cpu.cores !== '—') ? `${cpu.cores} Cores / ${cpu.threads || cpu.cores} Threads` : 'Architecture Matrix Active';
    if (specFreq) specFreq.textContent = `${cpu.baseFreq && cpu.baseFreq !== '—' ? cpu.baseFreq + ' Base' : 'Dynamic Clock'} • ${cpu.turboFreq && cpu.turboFreq !== '—' ? cpu.turboFreq + ' Boost' : 'Auto Boost'}`;
    if (specTdp) specTdp.textContent = `${cpu.tdp && cpu.tdp !== '—' ? cpu.tdp + ' TDP' : 'Adaptive Power'} • ${cpu.lithography && cpu.lithography !== '—' ? cpu.lithography : 'Silicon FinFET'}`;
    if (specMem) specMem.textContent = `${cpu.memoryChannels && cpu.memoryChannels !== '—' ? cpu.memoryChannels + ' Ch • ' : ''}${cpu.memoryTypes && cpu.memoryTypes !== '—' ? cpu.memoryTypes : 'System RAM'} ${cpu.maxMemory && cpu.maxMemory !== '—' ? '(Max ' + cpu.maxMemory + ')' : ''}`;
    if (specSocket) specSocket.textContent = `${cpu.socket && cpu.socket !== '—' ? cpu.socket : 'Platform Socket'} • ${cpu.igpu && cpu.igpu !== '—' ? cpu.igpu : 'Compute Fabric'}`;
    if (specStatus) specStatus.textContent = `${cpu.status && cpu.status !== '—' ? cpu.status : 'Active'} ${cpu.releaseDate && cpu.releaseDate !== '—' ? '(' + cpu.releaseDate + ')' : ''} • ${cpu.segment && cpu.segment !== '—' ? cpu.segment : 'Architecture'}`;

    // Update Active Selected CPU Card
    const selName = document.getElementById('hw-selected-name');
    const selArch = document.getElementById('hw-selected-arch');
    const selNode = document.getElementById('hw-selected-node');
    const selSpecs = document.getElementById('hw-selected-specs');

    if (selName) selName.textContent = cpu.name || cpuKey;
    if (selArch) selArch.textContent = cpu.family || 'x86_64 Architecture';
    if (selNode) selNode.textContent = (cpu.lithography && cpu.lithography !== '—') ? cpu.lithography : 'Silicon FinFET';
    if (selSpecs) {
      const parts = [];
      if (cpu.cores && cpu.cores !== '—') parts.push(`${cpu.cores} Cores / ${cpu.threads || cpu.cores} Threads`);
      if (cpu.baseFreq && cpu.baseFreq !== '—') parts.push(`${cpu.baseFreq} Base`);
      if (cpu.turboFreq && cpu.turboFreq !== '—') parts.push(`${cpu.turboFreq} Boost`);
      if (cpu.tdp && cpu.tdp !== '—') parts.push(`${cpu.tdp} TDP`);
      if (cpu.socket && cpu.socket !== '—') parts.push(cpu.socket);
      selSpecs.textContent = parts.join(' • ') || 'Verified Hardware Profile';
    }

    if (vramStatVal && vramBarFill) {
      if (gpu.isUnified) {
        vramStatVal.textContent = vramUsedGB + ' GB dynamic unified pool (of ' + ram.capacity + ' GB total)';
        vramBarFill.style.width = vramPercent + '%';
      } else if (gpu.isCpuOnly) {
        vramStatVal.textContent = 'None (0 GB Dedicated VRAM) • Zero-Copy Host RAM Engine';
        vramBarFill.style.width = '0%';
      } else {
        vramStatVal.textContent = vramUsedGB + ' GB allocated of ' + vramTotalGB + ' GB GDDR';
        vramBarFill.style.width = vramPercent + '%';
      }
    }

    if (ramStatVal && ramBarFill) {
      ramStatVal.textContent = ramUsedGB + ' GB in use (' + ram.capacity + ' GB physical)';
      ramBarFill.style.width = ramPercent + '%';
    }
  }

  cpuSelect.addEventListener('change', recalculate);
  gpuSelect.addEventListener('change', recalculate);
  ramSelect.addEventListener('change', recalculate);

  // Initialize Custom CPU Selector & Autocomplete
  initCustomCpuSelector(cpuSelect, recalculate);

  // Initialize Mega Directory Modal
  initMegaDirectory(cpuSelect, recalculate);

  recalculate();
}

/* ==========================================================================
   12. Sleek Custom CPU Selector & Autocomplete Controller
   ========================================================================== */
function initCustomCpuSelector(cpuSelect, recalculate) {
  const searchInput = document.getElementById('hw-cpu-search-input');
  const searchClearBtn = document.getElementById('hw-search-clear-btn');
  const searchDropdown = document.getElementById('hw-search-results-dropdown');
  const resultsList = document.getElementById('hw-results-list');
  const resultsCount = document.getElementById('hw-results-count');
  const openSearchBtn = document.getElementById('hw-open-search-btn');
  const selectedCpuCard = document.getElementById('hw-selected-cpu-card');
  const counterText = document.getElementById('hw-counter-text');
  const quickFilters = document.querySelectorAll('#hw-quick-filters .hw-quick-filter');
  const searchContainer = document.getElementById('hw-custom-search-box');

  if (!searchInput || !resultsList || !cpuSelect) return;

  function safeEscape(str) {
    if (!str) return '';
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  // Build indexed CPU repository (filtering out internal meta-keys)
  const metaKeys = ['amd-zen5-ai', 'amd-zen4', 'amd-zen3', 'intel-ultra2', 'intel-ultra1', 'intel-13-14'];
  const allCpus = [];

  for (const [key, cpu] of Object.entries(HW_DATABASE.cpus)) {
    if (metaKeys.includes(key)) continue;

    let familyGroup = 'other';
    const lk = key.toLowerCase();
    const ln = (cpu.name || '').toLowerCase();
    const lf = (cpu.family || '').toLowerCase();

    const isCoreSeries = (
      (ln.includes('core 3') || ln.includes('core 5') || ln.includes('core 7') || ln.includes('core 9')) &&
      !ln.includes('core ultra') &&
      !lk.includes('ultra') &&
      !/\bi[3579]-/i.test(ln) &&
      !/\bcore 2\b/i.test(ln)
    ) || lk.includes('core-3-') || lk.includes('core-5-') || lk.includes('core-7-') || lf.includes('core series');

    if (lk.includes('ultra') || ln.includes('core ultra') || lf.includes('arrow') || lf.includes('lunar') || lf.includes('meteor')) {
      familyGroup = 'intel-ultra';
    } else if (isCoreSeries) {
      familyGroup = 'intel-core-series';
    } else if (lk.startsWith('intel-') && (/\bi[3579]-(14|13|12|11|10)/i.test(ln) || ln.includes('14th gen') || ln.includes('13th gen') || ln.includes('12th gen') || ln.includes('11th gen') || ln.includes('10th gen') || ((ln.includes('14') || ln.includes('13') || ln.includes('12') || ln.includes('11') || ln.includes('10')) && /\bi[3579]/i.test(ln)))) {
      familyGroup = 'intel-core-modern';
    } else if (lk.startsWith('intel-') && (ln.includes('xeon') || lf.includes('xeon') || lf.includes('emerald') || lf.includes('sapphire') || lf.includes('granite'))) {
      familyGroup = 'intel-xeon';
    } else if (lk.startsWith('intel-') && (ln.includes('atom') || ln.includes('pentium') || ln.includes('celeron') || ln.includes('processor ') || ln.includes('n100') || ln.includes('n200') || ln.includes('n97') || ln.includes('n95') || ln.includes('300'))) {
      familyGroup = 'intel-entry';
    } else if (lk.startsWith('intel-')) {
      familyGroup = 'intel-core-legacy';
    } else if (lk.startsWith('amd-') && (ln.includes('epyc') || ln.includes('threadripper'))) {
      familyGroup = 'amd-epyc';
    } else if (lk.startsWith('amd-')) {
      familyGroup = 'amd-ryzen';
    } else if (lk.includes('apple') || lk.includes('snapdragon') || lk.includes('qualcomm') || lk.includes('arm') || lf.includes('arm')) {
      familyGroup = 'arm';
    } else if (lk.includes('server') || ln.includes('server')) {
      familyGroup = 'amd-epyc';
    }

    const searchTokens = [
      cpu.name || '',
      key,
      cpu.family || '',
      cpu.socket || '',
      cpu.cores ? `${cpu.cores}c` : '',
      cpu.tdp || '',
      cpu.lithography || '',
      cpu.driver || '',
      cpu.segment || '',
      'chip chips cpu cpus processor processors silicon'
    ].join(' ').toLowerCase();

    allCpus.push({
      key,
      cpu,
      familyGroup,
      searchTokens
    });
  }

  // Update counter badge with exact catalog count
  if (counterText) {
    counterText.textContent = `${allCpus.length.toLocaleString()} Processors Cataloged`;
  }

  // Update 'All' quick filter pill with exact count
  const allFilterBtn = document.querySelector('#hw-quick-filters .hw-quick-filter[data-filter="all"]');
  if (allFilterBtn) {
    allFilterBtn.textContent = `All (${allCpus.length.toLocaleString()})`;
  }

  const genericWords = new Set(['chip', 'chips', 'cpu', 'cpus', 'processor', 'processors', 'silicon']);

  function scoreItem(item, q, rawTokens) {
    let score = 0;
    const nameLower = (item.cpu.name || '').toLowerCase();
    const keyLower = item.key.toLowerCase();
    const isCoreSeries = item.familyGroup === 'intel-core-series';
    const isUltra = item.familyGroup === 'intel-ultra';
    const isISeries = item.familyGroup === 'intel-core-modern' || item.familyGroup === 'intel-core-legacy';

    if (nameLower.includes(q)) score += 500;

    let queryTier = null;
    for (const t of ['3', '5', '7', '9']) {
      if (new RegExp('(^|[^a-z0-9])(core|ultra|i)?\\s*' + t + '([^a-z0-9]|$)', 'i').test(q)) {
        queryTier = t;
        break;
      }
    }

    const wantsCoreSeries = (q.includes('core') || q.includes('intel core')) && !q.includes('ultra') && !/\bi[3579]/i.test(q);

    if (queryTier) {
      if (new RegExp('core\\s+' + queryTier + '\\b', 'i').test(nameLower) && !isUltra && !isISeries) {
        score += 3000;
      } else if (new RegExp('ultra\\s+' + queryTier + '\\b', 'i').test(nameLower)) {
        score += 1500;
      } else if (new RegExp('i' + queryTier + '-', 'i').test(nameLower)) {
        score += 1200;
      } else {
        score -= 500;
      }
    } else if (wantsCoreSeries) {
      if (isCoreSeries) score += 2000;
      else if (isUltra) score += 600;
      else if (isISeries) score += 400;
    }

    for (const tok of rawTokens) {
      if (tok.length >= 2 && !genericWords.has(tok)) {
        const wholeWord = new RegExp('(^|[^a-z0-9])' + tok + '([^a-z0-9]|$)', 'i');
        if (wholeWord.test(nameLower) || wholeWord.test(keyLower)) {
          score += 800;
        } else if (nameLower.includes(tok) || keyLower.includes(tok)) {
          score += 200;
        }
      }
    }

    score += Math.round((item.cpu.factor || 1.0) * 10);
    return score;
  }

  let activeFilter = 'all';
  let activeQuery = '';
  let debounceTimer = null;
  let focusedIndex = -1;

  function renderResults() {
    const q = activeQuery.trim();
    const rawTokens = q ? q.toLowerCase().split(/\s+/).filter(Boolean) : [];
    const meaningfulTokens = rawTokens.filter(t => !genericWords.has(t));
    const tokensToCheck = meaningfulTokens.length > 0 ? meaningfulTokens : rawTokens;

    const matchedItems = [];

    for (const item of allCpus) {
      if (activeFilter !== 'all' && item.familyGroup !== activeFilter) {
        continue;
      }

      let matched = true;
      for (const tok of tokensToCheck) {
        if (/^[3579]$/.test(tok)) {
          const digitRegex = new RegExp('(^|[^0-9a-z])(i|ultra\\s*|core\\s*|ryzen\\s*)?' + tok + '([^0-9a-z]|$)', 'i');
          if (!digitRegex.test(item.searchTokens)) {
            matched = false;
            break;
          }
        } else {
          if (!item.searchTokens.includes(tok)) {
            matched = false;
            break;
          }
        }
      }

      if (matched) {
        const score = (q.length > 0) ? scoreItem(item, q.toLowerCase(), rawTokens) : 0;
        matchedItems.push({ item, score });
      }
    }

    if (q.length > 0) {
      matchedItems.sort((a, b) => b.score - a.score);
    }

    const matches = matchedItems.map(m => m.item);

    if (resultsCount) {
      if (rawTokens.length > 0 || activeFilter !== 'all') {
        resultsCount.textContent = `Found ${matches.length.toLocaleString()} of ${allCpus.length.toLocaleString()} Processors`;
      } else {
        resultsCount.textContent = `All Processors (${allCpus.length.toLocaleString()})`;
      }
    }

    if (counterText) {
      if (rawTokens.length > 0 || activeFilter !== 'all') {
        counterText.textContent = `Showing ${matches.length.toLocaleString()} of ${allCpus.length.toLocaleString()} Processors`;
      } else {
        counterText.textContent = `${allCpus.length.toLocaleString()} Processors Cataloged`;
      }
    }

    const displayItems = matches.slice(0, 50);

    if (displayItems.length === 0) {
      resultsList.innerHTML = `
        <div style="padding: 1.75rem 1rem; text-align: center; color: rgba(255, 255, 255, 0.5); font-size: 0.85rem;">
          No processors found matching "<strong>${safeEscape(q)}</strong>".<br />
          <span style="display:inline-block; margin-top:0.35rem; font-size:0.75rem; color: rgba(255,255,255,0.35);">
            Use the Mega Directory button to browse all ${allCpus.length.toLocaleString()} entries by family.
          </span>
        </div>`;
      focusedIndex = -1;
      return;
    }

    const currentKey = cpuSelect.value;
    const fragment = document.createDocumentFragment();

    displayItems.forEach((item, index) => {
      const cpu = item.cpu;
      const isSelected = item.key === currentKey;
      const el = document.createElement('div');
      el.className = `hw-result-item${isSelected ? ' selected' : ''}`;
      el.setAttribute('data-key', item.key);
      el.setAttribute('data-index', String(index));
      el.setAttribute('role', 'option');
      el.setAttribute('aria-selected', isSelected ? 'true' : 'false');

      const coreText = cpu.cores && cpu.cores !== '—' ? `${cpu.cores}C / ${cpu.threads || cpu.cores}T` : '';
      const clockText = cpu.turboFreq && cpu.turboFreq !== '—' ? cpu.turboFreq : (cpu.baseFreq && cpu.baseFreq !== '—' ? cpu.baseFreq : '');
      const factorBadge = cpu.factor ? `${cpu.factor}x Factor` : '1.0x Factor';

      el.innerHTML = `
        <div class="hw-result-top">
          <span class="hw-result-name">${safeEscape(cpu.name || item.key)}</span>
          <span class="hw-result-badge-factor">${factorBadge}</span>
        </div>
        <div class="hw-result-meta">
          <span class="hw-result-tag">${safeEscape(cpu.family || 'x86_64')}</span>
          ${coreText ? `<span class="hw-result-tag">${coreText}</span>` : ''}
          ${clockText ? `<span class="hw-result-tag">${clockText}</span>` : ''}
          ${cpu.tdp && cpu.tdp !== '—' ? `<span class="hw-result-tag">${safeEscape(cpu.tdp)}</span>` : ''}
          ${cpu.socket && cpu.socket !== '—' ? `<span class="hw-result-tag">${safeEscape(cpu.socket)}</span>` : ''}
          ${cpu.lithography && cpu.lithography !== '—' ? `<span class="hw-result-tag">${safeEscape(cpu.lithography)}</span>` : ''}
          ${cpu.npuSupported ? `<span class="hw-result-tag highlight">NPU AI Engine</span>` : ''}
        </div>
      `;

      fragment.appendChild(el);
    });

    resultsList.innerHTML = '';
    resultsList.appendChild(fragment);
    focusedIndex = -1;
  }

  function selectCpu(key) {
    if (!key || !HW_DATABASE.cpus[key]) return;
    cpuSelect.value = key;
    cpuSelect.dispatchEvent(new Event('change'));
    closeDropdown();
  }

  function openDropdown() {
    if (searchDropdown) {
      searchDropdown.style.display = 'flex';
      renderResults();
    }
  }

  function closeDropdown() {
    if (searchDropdown) {
      searchDropdown.style.display = 'none';
      focusedIndex = -1;
    }
  }

  // Results list click selection
  resultsList.addEventListener('click', (e) => {
    const itemEl = e.target.closest('.hw-result-item');
    if (!itemEl) return;
    const key = itemEl.getAttribute('data-key');
    if (key) {
      selectCpu(key);
    }
  });

  // Focus & input handlers
  searchInput.addEventListener('focus', openDropdown);

  searchInput.addEventListener('input', (e) => {
    activeQuery = e.target.value;
    if (searchClearBtn) {
      searchClearBtn.style.display = activeQuery ? 'flex' : 'none';
    }
    openDropdown();
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(renderResults, 60);
  });

  // Clear button
  if (searchClearBtn) {
    searchClearBtn.addEventListener('click', () => {
      searchInput.value = '';
      activeQuery = '';
      searchClearBtn.style.display = 'none';
      renderResults();
      searchInput.focus();
    });
  }

  // Open search buttons & card click
  if (openSearchBtn) {
    openSearchBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      openDropdown();
      searchInput.focus();
      searchInput.select();
    });
  }

  const selCpuMain = document.querySelector('.hw-selected-cpu-main');
  if (selCpuMain) {
    selCpuMain.style.cursor = 'pointer';
    selCpuMain.addEventListener('click', () => {
      openDropdown();
      searchInput.focus();
      searchInput.select();
    });
  }

  // Quick Architecture Filter Pills
  quickFilters.forEach(btn => {
    btn.addEventListener('click', () => {
      quickFilters.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      activeFilter = btn.getAttribute('data-filter') || 'all';
      openDropdown();
      renderResults();
    });
  });

  // Keyboard navigation inside search dropdown
  searchInput.addEventListener('keydown', (e) => {
    const items = resultsList.querySelectorAll('.hw-result-item');
    if (!items.length) return;

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      focusedIndex = (focusedIndex + 1) % items.length;
      items.forEach((it, idx) => {
        if (idx === focusedIndex) {
          it.style.background = 'rgba(94, 92, 230, 0.25)';
          it.scrollIntoView({ block: 'nearest' });
        } else {
          it.style.background = '';
        }
      });
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      focusedIndex = (focusedIndex - 1 + items.length) % items.length;
      items.forEach((it, idx) => {
        if (idx === focusedIndex) {
          it.style.background = 'rgba(94, 92, 230, 0.25)';
          it.scrollIntoView({ block: 'nearest' });
        } else {
          it.style.background = '';
        }
      });
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (focusedIndex >= 0 && items[focusedIndex]) {
        const key = items[focusedIndex].getAttribute('data-key');
        if (key) selectCpu(key);
      } else if (items[0]) {
        const key = items[0].getAttribute('data-key');
        if (key) selectCpu(key);
      }
    } else if (e.key === 'Escape') {
      closeDropdown();
      searchInput.blur();
    }
  });

  // Dismiss dropdown on outside clicks
  document.addEventListener('click', (e) => {
    if (
      searchContainer &&
      !searchContainer.contains(e.target) &&
      (!selectedCpuCard || !selectedCpuCard.contains(e.target))
    ) {
      closeDropdown();
    }
  });
}

/* ==========================================================================
   12.1 Mega Silicon Directory Modal Viewer
   ========================================================================== */
function initMegaDirectory(cpuSelect, recalculate) {
  const modal = document.getElementById('hw-mega-modal');
  const openBtn = document.getElementById('hw-mega-list-btn');
  const closeBtn = document.getElementById('hw-mega-close-btn');
  const footerCloseBtn = document.getElementById('hw-mega-footer-close');
  const backdrop = document.getElementById('hw-mega-backdrop');
  const searchInput = document.getElementById('hw-mega-search-input');
  const matchCounter = document.getElementById('hw-mega-match-counter');
  const tableBody = document.getElementById('hw-mega-table-body');
  const tableContainer = document.querySelector('.hw-mega-table-container');
  const filterChips = document.querySelectorAll('.hw-filter-chip');

  if (!modal || !openBtn || !tableBody) return;

  const allEntries = [];
  const totalCounterEl = document.getElementById('hw-mega-total-count');

  for (const [key, cpu] of Object.entries(HW_DATABASE.cpus)) {
    if (['amd-zen5-ai', 'amd-zen4', 'amd-zen3', 'intel-ultra2', 'intel-ultra1', 'intel-13-14'].includes(key)) continue;

    let familyGroup = 'other';
    const lk = key.toLowerCase();
    const ln = (cpu.name || '').toLowerCase();
    const lf = (cpu.family || '').toLowerCase();

    const isCoreSeries = (
      (ln.includes('core 3') || ln.includes('core 5') || ln.includes('core 7') || ln.includes('core 9')) &&
      !ln.includes('core ultra') &&
      !lk.includes('ultra') &&
      !/\bi[3579]-/i.test(ln) &&
      !/\bcore 2\b/i.test(ln)
    ) || lk.includes('core-3-') || lk.includes('core-5-') || lk.includes('core-7-') || lf.includes('core series');

    if (lk.includes('ultra') || ln.includes('core ultra') || lf.includes('arrow') || lf.includes('lunar') || lf.includes('meteor')) {
      familyGroup = 'intel-ultra';
    } else if (isCoreSeries) {
      familyGroup = 'intel-core-series';
    } else if (lk.startsWith('intel-') && (/\bi[3579]-(14|13|12|11|10)/i.test(ln) || ln.includes('14th gen') || ln.includes('13th gen') || ln.includes('12th gen') || ln.includes('11th gen') || ln.includes('10th gen') || ((ln.includes('14') || ln.includes('13') || ln.includes('12') || ln.includes('11') || ln.includes('10')) && /\bi[3579]/i.test(ln)))) {
      familyGroup = 'intel-core-modern';
    } else if (lk.startsWith('intel-') && (ln.includes('xeon') || lf.includes('xeon') || lf.includes('emerald') || lf.includes('sapphire') || lf.includes('granite'))) {
      familyGroup = 'intel-xeon';
    } else if (lk.startsWith('intel-') && (ln.includes('atom') || ln.includes('pentium') || ln.includes('celeron') || ln.includes('processor ') || ln.includes('n100') || ln.includes('n200') || ln.includes('n97') || ln.includes('n95') || ln.includes('300'))) {
      familyGroup = 'intel-entry';
    } else if (lk.startsWith('intel-')) {
      familyGroup = 'intel-core-legacy';
    } else if (lk.startsWith('amd-') && (ln.includes('epyc') || ln.includes('threadripper'))) {
      familyGroup = 'amd-epyc';
    } else if (lk.startsWith('amd-')) {
      familyGroup = 'amd-ryzen';
    } else if (lk.includes('apple') || lk.includes('snapdragon') || lk.includes('qualcomm') || lk.includes('arm') || lf.includes('arm')) {
      familyGroup = 'arm';
    } else if (lk.includes('server') || ln.includes('server')) {
      familyGroup = 'amd-epyc';
    }

    allEntries.push({
      key,
      cpu,
      familyGroup,
      searchStr: `${cpu.name} ${key} ${cpu.family} ${cpu.cores} ${cpu.socket} ${cpu.driver} ${cpu.tdp} ${cpu.lithography} chip chips cpu cpus processor processors silicon`.toLowerCase()
    });
  }

  if (totalCounterEl) {
    totalCounterEl.textContent = allEntries.length.toLocaleString();
  }

  const genericWords = new Set(['chip', 'chips', 'cpu', 'cpus', 'processor', 'processors', 'silicon']);

  function scoreMegaItem(item, q, rawTokens) {
    let score = 0;
    const nameLower = (item.cpu.name || '').toLowerCase();
    const keyLower = item.key.toLowerCase();
    const isCoreSeries = item.familyGroup === 'intel-core-series';
    const isUltra = item.familyGroup === 'intel-ultra';
    const isISeries = item.familyGroup === 'intel-core-modern' || item.familyGroup === 'intel-core-legacy';

    if (nameLower.includes(q)) score += 500;

    let queryTier = null;
    for (const t of ['3', '5', '7', '9']) {
      if (new RegExp('(^|[^a-z0-9])(core|ultra|i)?\\s*' + t + '([^a-z0-9]|$)', 'i').test(q)) {
        queryTier = t;
        break;
      }
    }

    const wantsCoreSeries = (q.includes('core') || q.includes('intel core')) && !q.includes('ultra') && !/\bi[3579]/i.test(q);

    if (queryTier) {
      if (new RegExp('core\\s+' + queryTier + '\\b', 'i').test(nameLower) && !isUltra && !isISeries) {
        score += 3000;
      } else if (new RegExp('ultra\\s+' + queryTier + '\\b', 'i').test(nameLower)) {
        score += 1500;
      } else if (new RegExp('i' + queryTier + '-', 'i').test(nameLower)) {
        score += 1200;
      } else {
        score -= 500;
      }
    } else if (wantsCoreSeries) {
      if (isCoreSeries) score += 2000;
      else if (isUltra) score += 600;
      else if (isISeries) score += 400;
    }

    for (const tok of rawTokens) {
      if (tok.length >= 2 && !genericWords.has(tok)) {
        const wholeWord = new RegExp('(^|[^a-z0-9])' + tok + '([^a-z0-9]|$)', 'i');
        if (wholeWord.test(nameLower) || wholeWord.test(keyLower)) {
          score += 800;
        } else if (nameLower.includes(tok) || keyLower.includes(tok)) {
          score += 200;
        }
      }
    }

    score += Math.round((item.cpu.factor || 1.0) * 10);
    return score;
  }

  let activeFamily = 'all';
  let activeSearch = '';
  let filteredItems = allEntries;
  let renderedCount = 0;
  const CHUNK_SIZE = 60;

  function applyFilter() {
    const q = activeSearch;
    const rawTokens = q ? q.toLowerCase().split(/\s+/).filter(Boolean) : [];
    const meaningfulTokens = rawTokens.filter(t => !genericWords.has(t));
    const tokensToCheck = meaningfulTokens.length > 0 ? meaningfulTokens : rawTokens;

    const matchedEntries = [];

    for (const item of allEntries) {
      if (activeFamily !== 'all' && item.familyGroup !== activeFamily) {
        continue;
      }

      let matched = true;
      for (const tok of tokensToCheck) {
        if (/^[3579]$/.test(tok)) {
          const digitRegex = new RegExp('(^|[^0-9a-z])(i|ultra\\s*|core\\s*|ryzen\\s*)?' + tok + '([^0-9a-z]|$)', 'i');
          if (!digitRegex.test(item.searchStr)) {
            matched = false;
            break;
          }
        } else {
          if (!item.searchStr.includes(tok)) {
            matched = false;
            break;
          }
        }
      }

      if (matched) {
        const score = (q.length > 0) ? scoreMegaItem(item, q, rawTokens) : 0;
        matchedEntries.push({ item, score });
      }
    }

    if (q.length > 0) {
      matchedEntries.sort((a, b) => b.score - a.score);
    }

    filteredItems = matchedEntries.map(m => m.item);

    if (matchCounter) {
      matchCounter.textContent = `Showing ${filteredItems.length.toLocaleString()} of ${allEntries.length.toLocaleString()} CPUs`;
    }

    tableBody.innerHTML = '';
    renderedCount = 0;
    renderNextChunk();
  }

  function renderNextChunk() {
    if (renderedCount >= filteredItems.length) return;
    const nextBatch = filteredItems.slice(renderedCount, renderedCount + CHUNK_SIZE);
    const fragment = document.createDocumentFragment();

    nextBatch.forEach(item => {
      const cpu = item.cpu;
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td>
          <span class="hw-mega-name-cell">${cpu.name || item.key}</span>
          <span class="hw-mega-sub-tag">${cpu.segment || 'Desktop'} • ${cpu.status || 'Active'}</span>
        </td>
        <td>
          <span>${cpu.family || 'x86_64'}</span>
          <span class="hw-mega-sub-tag">${cpu.lithography || 'FinFET'}</span>
        </td>
        <td>${cpu.cores && cpu.cores !== '—' ? cpu.cores + 'C / ' + (cpu.threads || cpu.cores) + 'T' : '—'}</td>
        <td>${cpu.baseFreq && cpu.baseFreq !== '—' ? cpu.baseFreq : '—'} / ${cpu.turboFreq && cpu.turboFreq !== '—' ? cpu.turboFreq : '—'}</td>
        <td><span class="hw-counter-pill" style="padding:0.15rem 0.5rem;font-size:0.7rem;">${cpu.tdp || '—'}</span></td>
        <td>${cpu.socket || 'Integrated'}</td>
        <td><span style="font-size:0.75rem;color:rgba(255,255,255,0.6);">${cpu.driver || 'Linux LTS'}</span></td>
        <td style="text-align: right;">
          <button type="button" class="hw-mega-select-btn" data-key="${item.key}">Select</button>
        </td>
      `;
      fragment.appendChild(tr);
    });

    tableBody.appendChild(fragment);
    renderedCount += nextBatch.length;
  }

  if (tableContainer) {
    tableContainer.addEventListener('scroll', () => {
      if (tableContainer.scrollTop + tableContainer.clientHeight >= tableContainer.scrollHeight - 150) {
        renderNextChunk();
      }
    });
  }

  tableBody.addEventListener('click', (e) => {
    const btn = e.target.closest('.hw-mega-select-btn');
    if (!btn) return;
    const selectedKey = btn.getAttribute('data-key');
    if (selectedKey && cpuSelect) {
      cpuSelect.value = selectedKey;
      cpuSelect.dispatchEvent(new Event('change'));
      closeModal();
      const hwSection = document.getElementById('hardware');
      if (hwSection) {
        hwSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }
  });

  filterChips.forEach(chip => {
    chip.addEventListener('click', () => {
      filterChips.forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
      activeFamily = chip.getAttribute('data-family') || 'all';
      applyFilter();
    });
  });

  if (searchInput) {
    let debounceTimer;
    searchInput.addEventListener('input', (e) => {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(() => {
        activeSearch = e.target.value.toLowerCase().trim();
        applyFilter();
      }, 120);
    });
  }

  function openModal() {
    modal.style.display = 'flex';
    requestAnimationFrame(() => {
      modal.classList.add('open');
      document.body.style.overflow = 'hidden';
      if (searchInput) {
        searchInput.value = '';
        activeSearch = '';
      }
      applyFilter();
      if (searchInput) searchInput.focus();
    });
  }

  function closeModal() {
    modal.classList.remove('open');
    document.body.style.overflow = '';
    setTimeout(() => {
      modal.style.display = 'none';
    }, 250);
  }

  openBtn.addEventListener('click', openModal);
  if (closeBtn) closeBtn.addEventListener('click', closeModal);
  if (footerCloseBtn) footerCloseBtn.addEventListener('click', closeModal);
  if (backdrop) backdrop.addEventListener('click', closeModal);

  window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && modal.classList.contains('open')) {
      closeModal();
    }
  });
}

/* ==========================================================================
   13. Interactive Hardware Documentation Tabs Switcher
   ========================================================================== */
function initHardwareDocsTabs() {
  const tabs = document.querySelectorAll('.hw-docs-tab');
  const panels = document.querySelectorAll('.hw-docs-panel');
  if (!tabs.length || !panels.length) return;

  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      const targetId = tab.getAttribute('data-tab');
      tabs.forEach(t => t.classList.remove('active'));
      panels.forEach(p => p.classList.remove('active'));

      tab.classList.add('active');
      const activePanel = document.getElementById(targetId);
      if (activePanel) {
        activePanel.classList.add('active');
      }
    });

    tab.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
        e.preventDefault();
        const tabList = Array.from(tabs);
        const currentIndex = tabList.indexOf(tab);
        let nextIndex;
        if (e.key === 'ArrowRight') {
          nextIndex = (currentIndex + 1) % tabList.length;
        } else {
          nextIndex = (currentIndex - 1 + tabList.length) % tabList.length;
        }
        tabList[nextIndex].focus();
        tabList[nextIndex].click();
      }
    });
  });
}
